67	func buildToolFromOperation(operation *openAPIOperation) (*sdkmcp.Tool, *registeredOperation) {
68		name := toolNameFromOperationID(operation.OperationID)
69		title := titleFromToolName(name)
70		inputSchema := inputSchemaForOperation(operation)
71		tool := &sdkmcp.Tool{
72			Meta: sdkmcp.Meta{
73				"operationId": operation.OperationID,
74				"method":      operation.Method,
75				"path":        operation.Path,
76			},
77			Name:         name,
78			Title:        title,
79			Description:  operation.Description,
80			InputSchema:  inputSchema,
81			OutputSchema: outputSchemaForOperation(operation),
82			Annotations:  annotationsForOperation(operation, title),
83		}
84	
85		return tool, &registeredOperation{
86			ToolName:    name,
87			OperationID: operation.OperationID,
88			Method:      operation.Method,
89			Path:        operation.Path,
90			Operation:   operation,
91			InputSchema: inputSchema,
92		}
93	}
