95	func toolNameFromOperationID(operationID string) string {
96		service, method, ok := strings.Cut(operationID, "_")
97		if !ok {
98			return camelToSnake(operationID)
99		}
100		service = strings.TrimSuffix(service, "Service")
101		return camelToSnake(service) + "_" + camelToSnake(method)
102	}
103	
104	func camelToSnake(value string) string {
105		return strings.ToLower(wordBoundary.ReplaceAllString(value, `${1}_${2}`))
106	}
107	
108	func titleFromToolName(name string) string {
109		parts := strings.Split(name, "_")
110		for i, part := range parts {
111			if part == "" {
112				continue
113			}
114			parts[i] = strings.ToUpper(part[:1]) + part[1:]
115		}
116		return strings.Join(parts, " ")
117	}
