119	func inputSchemaForOperation(operation *openAPIOperation) jsonSchema {
120		properties := map[string]any{}
121		required := []string{}
122		defs := map[string]any{}
123		for _, parameter := range operation.Parameters {
124			schema := cloneSchema(parameter.Schema)
125			if parameter.Description != "" {
126				schema["description"] = parameter.Description
127			}
128			properties[parameter.Name] = schema
129			if parameter.Required {
130				required = append(required, parameter.Name)
131			}
132		}
133	
134		if operation.RequestBody != nil {
135			bodySchema := requestBodySchema(operation)
136			for name, definition := range extractSchemaDefs(bodySchema) {
137				defs[name] = definition
138			}
139			properties["body"] = bodySchema
140			if operation.RequestBody.Required {
141				required = append(required, "body")
142			}
143		}
144	
145		schema := jsonSchema{
146			"type":                 "object",
147			"properties":           properties,
148			"additionalProperties": false,
149		}
150		if len(required) > 0 {
151			schema["required"] = required
152		}
153		if len(defs) > 0 {
154			schema["$defs"] = defs
155		}
156		return schema
157	}
158	
159	func requestBodySchema(operation *openAPIOperation) jsonSchema {
160		if operation.RequestBodySchema == nil {
161			return jsonSchema{"type": "object"}
162		}
163		return cloneSchema(operation.RequestBodySchema)
164	}
165	
166	func outputSchemaForOperation(operation *openAPIOperation) jsonSchema {
167		if operation.ResponseSchema == nil {
168			return okSchema()
169		}
170		return cloneSchema(operation.ResponseSchema)
171	}
172	
173	func cloneSchema(schema jsonSchema) jsonSchema {
174		clone := jsonSchema{}
175		for key, value := range schema {
176			clone[key] = value
177		}
178		return clone
179	}
180	
181	func extractSchemaDefs(schema jsonSchema) map[string]any {
182		defs, ok := schema["$defs"].(map[string]any)
183		if !ok {
184			return nil
185		}
186		delete(schema, "$defs")
187		return defs
188	}
