210	func annotationsForMethod(method string, title string) *sdkmcp.ToolAnnotations {
211		openWorld := false
212		destructive := false
213		switch strings.ToUpper(method) {
214		case "GET":
215			return &sdkmcp.ToolAnnotations{
216				Title:           title,
217				ReadOnlyHint:    true,
218				DestructiveHint: &destructive,
219				IdempotentHint:  true,
220				OpenWorldHint:   &openWorld,
221			}
222		case "DELETE":
223			destructive = true
224			return &sdkmcp.ToolAnnotations{
225				Title:           title,
226				ReadOnlyHint:    false,
227				DestructiveHint: &destructive,
228				IdempotentHint:  true,
229				OpenWorldHint:   &openWorld,
230			}
231		default:
232			return &sdkmcp.ToolAnnotations{
233				Title:           title,
234				ReadOnlyHint:    false,
235				DestructiveHint: &destructive,
236				IdempotentHint:  false,
237				OpenWorldHint:   &openWorld,
238			}
239		}
